          "status": "supported"
        },
        "2": {
          "evidence": "The horizontal axis label is 'Advertising Spend ($ thousands)'. The visible ticks include 30, 40, 50, 60, and 70 (as well as others like 25, 35, etc.).",
          "status": "supported"
        },
        "3": {
          "evidence": "The vertical axis label is 'Sales ($ thousands)'. The visible ticks range from 60 to 170 in increments of 10.",
          "status": "supported"
